'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=t=>{const m=Math.floor(t/60);return `${String(m).padStart(2,'0')}:${(t%60).toFixed(2).padStart(5,'0')}`};
const SIZES={"none":"无景别","extreme-wide":"大远景","wide":"全景","medium-wide":"中远景","medium":"中景","medium-close":"中近景","close":"特写","extreme-close":"大特写"};
const CATS={"establishing":"定场","subject":"主体动作","dialogue":"对白","reaction":"反应","insert":"局部细节","pov":"主观","empty":"空镜","product":"产品展示","text-card":"字卡","transition":"转场镜头","archive":"引用素材"};
const CAMS={"static":"固定","push-in":"推近","pull-out":"拉远","zoom-in":"变焦推","zoom-out":"变焦拉","pan-left":"左摇","pan-right":"右摇","tilt-up":"上摇","tilt-down":"下摇","truck-left":"左移","truck-right":"右移","pedestal-up":"升","pedestal-down":"降","tracking":"跟拍","arc":"环绕","whip-pan":"甩镜","handheld":"手持微晃","shake":"剧烈晃动","rack-focus":"焦点转移","micro-push":"微推","roll":"旋转","drone":"航拍移动"};
const video=$('#film');
let currentIndex=0, stopAt=null, queuedSeek=null, term='',category='all',castId='',sort='timeline',frameShot=0,framePick='a',promptIndex=0;
let toastTimer, frameHandle=null, frameTimer=null, segmentCompleted=false;
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3000)}
function castName(id){return DOC.cast.find(c=>c.id===id)?.name||id}
function filterShots(){return DOC.shots.filter(s=>(category==='all'||s.category===category)&&(!castId||s.subjects.includes(castId))&&(!term||[s.id,s.title,s.frame,s.fight,s.audio,s.cameraRead,s.spatial,...s.subjects.map(castName)].join(' ').toLowerCase().includes(term))).sort((a,b)=>sort==='longest'?b.seconds-a.seconds:sort==='shortest'?a.seconds-b.seconds:a.start-b.start)}
function shotHTML(s){const n=DOC.shots.indexOf(s);return `<article class="shot" id="shot-${esc(s.id)}" data-shot="${esc(s.id)}" aria-current="${n===currentIndex}"><header class="shot-header"><div class="shot-heading"><span class="id">${esc(s.id)}</span><h3>${esc(s.title)}</h3><span class="range">${time(s.start)} → ${time(s.end)} · ${s.seconds.toFixed(2)}s</span></div><button data-seek="${s.start}">定位此镜 ↗</button></header><div class="shot-body"><div class="frames">${['a','b'].map((p,i)=>`<button class="frame-btn" data-frame="${esc(s.id)}:${p}" aria-label="放大 ${esc(s.id)} ${i?'后段帧':'前段帧'}"><img src="${esc(s.frames[p].src)}" alt="${esc(s.id)} ${i?'后段帧':'前段帧'}：${esc(s.frame)}" loading="lazy"><span>${i?'后段帧':'前段帧'} · ${s.frames[p].time===null?'取帧时间未记录':time(s.frames[p].time)+(s.frames[p].timeBasis==='decoded-pts'?' · PTS':' · 定位时间')}</span></button>`).join('')}</div><div class="scene"><span class="column-label">画面 / SCENE</span><p>${esc(s.frame)}</p><div class="meta-line">${esc(SIZES[s.size]||s.size)} · ${esc(CATS[s.category]||s.category)} · ${esc(CAMS[s.camera]||s.camera)}</div><div class="meta-line">主要：${(s.principalSubjects||s.subjects).map(id=>esc(castName(id))).join(' / ')}${s.backgroundSubjects?.length?`<br>背景：${s.backgroundSubjects.map(id=>esc(castName(id))).join(' / ')}`:''}</div></div><div class="fight"><span class="column-label red">${esc(DOC.report.actionLabel)} / ACTION</span><p>${esc(s.fight)}</p><ul class="beats">${s.beats.map(b=>`<li><span>${esc(b[0])}</span>${esc(b[1])}</li>`).join('')}</ul></div><div class="words"><span class="column-label">文字与声音 / WORDS</span><p>${s.audio?esc(s.audio):esc(DOC.report.audioFallback)}</p><div class="meta-line">${esc(s.rhythmNote)}</div></div></div><details class="shot-notes"><summary>展开：镜头变化、空间关系与复刻要点</summary><div class="note-grid"><div><b>摄影机与景别变化</b>${esc(s.cameraRead)}</div><div><b>空间与身份</b>${esc(s.spatial)}</div><div><b>重新制作怎么写</b>${esc(s.remake)}</div></div><p class="meta-line">判断依据：${esc(s.note)}</p></details></article>`}
function renderShots(){const shots=filterShots();$('#shot-list').innerHTML=shots.map(shotHTML).join('');$('#empty').hidden=shots.length>0;$('#result-count').textContent=`显示 ${shots.length} / ${DOC.shots.length} 镜${castId?' · '+castName(castId):''}`;$('#clear-filters').hidden=!(term||castId||category!=='all');$$('[data-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.category===category));$$('[data-cast]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.cast===castId))}
function sync(){let t=video.currentTime||0;if(stopAt!==null&&t>=stopAt-.002){t=Math.max(0,stopAt-1/DOC.meta.fps);stopAt=null;segmentCompleted=true;video.pause();video.currentTime=t;$('#media-state').textContent='本镜播放完毕'}const i=DOC.shots.findIndex(s=>t>=s.start && (t<s.end||s===DOC.shots.at(-1)));const index=i<0?0:i;const s=DOC.shots[index];$('#clock').textContent=`${time(t)} / ${time(DOC.meta.durationSeconds)}`;if(index!==currentIndex||!$('#current-title').textContent){currentIndex=index;$('#current-id').textContent=s.id;$('#current-title').textContent=s.title;$('#current-tags').textContent=`${time(s.start)}—${time(s.end)} · ${esc(SIZES[s.size]||s.size)} · ${esc(CAMS[s.camera]||s.camera)}`;$('#current-fight').textContent=s.fight;$('#current-camera').textContent=s.cameraRead;$$('[data-shot]').forEach(b=>b.setAttribute('aria-current',b.dataset.shot===s.id));$$('.segment').forEach(b=>b.setAttribute('aria-current',b.dataset.segment===s.id))}$$('.segment').forEach(b=>{const a=DOC.shots.find(s=>s.id===b.dataset.segment);b.style.setProperty('--played',`${Math.max(0,Math.min(1,(t-a.start)/a.seconds))*100}%`)})}
function seek(t,play=false,end=null,scroll=true){stopAt=end;segmentCompleted=false;const doSeek=()=>{video.currentTime=Math.min(Number(t),video.duration||DOC.meta.durationSeconds);sync();if(play)video.play().catch(e=>toast('播放未开始：'+e.message));else video.pause()};if(video.readyState<1)queuedSeek=doSeek;else doSeek();if(scroll)$('#watch').scrollIntoView({behavior:'smooth',block:'start'})}
video.addEventListener('loadedmetadata',()=>{if(queuedSeek){const f=queuedSeek;queuedSeek=null;f()}sync();$('#media-state').textContent='就绪'});
video.addEventListener('timeupdate',sync);video.addEventListener('seeked',sync);function stopFrameWatch(){if(frameHandle!==null){video.cancelVideoFrameCallback?.(frameHandle);frameHandle=null}if(frameTimer!==null){clearInterval(frameTimer);frameTimer=null}}function startFrameWatch(){stopFrameWatch();if(video.requestVideoFrameCallback){const frame=()=>{frameHandle=null;sync();if(!video.paused)frameHandle=video.requestVideoFrameCallback(frame)};frameHandle=video.requestVideoFrameCallback(frame)}else frameTimer=setInterval(sync,25)}
video.addEventListener('play',()=>{segmentCompleted=false;$('#media-state').textContent='播放中';startFrameWatch()});video.addEventListener('pause',()=>{stopFrameWatch();$('#media-state').textContent=segmentCompleted?'本镜播放完毕':video.ended?'全片播放完毕':'已暂停'});video.addEventListener('error',()=>$('#media-state').textContent='媒体加载失败，请尝试其他视频源或选择本地视频');
function changeSource(src,label){const t=video.currentTime;video.pause();stopAt=null;queuedSeek=()=>{video.currentTime=Math.min(t,video.duration||DOC.meta.durationSeconds);sync()};video.src=src;video.load();$('#media-label').textContent=label;$$('[data-source]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.source===src))}
$('#prev-shot').addEventListener('click',()=>seek(DOC.shots[Math.max(0,currentIndex-1)].start));$('#next-shot').addEventListener('click',()=>seek(DOC.shots[Math.min(DOC.shots.length-1,currentIndex+1)].start));$('#play-shot').addEventListener('click',()=>{const s=DOC.shots[currentIndex];seek(s.start,true,s.end,false)});
$('#search').addEventListener('input',e=>{term=e.target.value.trim().toLowerCase();renderShots()});$('#sort').addEventListener('change',e=>{sort=e.target.value;renderShots()});$('#clear-filters').addEventListener('click',()=>{term='';category='all';castId='';$('#search').value='';renderShots()});
function showFrame(id,p){frameShot=DOC.shots.findIndex(s=>s.id===id);framePick=p;const s=DOC.shots[frameShot];$('#frame-img').src=s.frames[p].src;$('#frame-img').alt=`${id} ${p==='a'?'前段帧':'后段帧'}：${s.frame}`;$('#frame-title').textContent=`${id} · ${s.title} · ${p==='a'?'前段帧':'后段帧'} · ${s.frames[p].time===null?'取帧时间未记录':time(s.frames[p].time)+(s.frames[p].timeBasis==='decoded-pts'?' · PTS':' · 定位时间')}`;if(!$('#frame-dialog').open)$('#frame-dialog').showModal()}
$('#frame-close').addEventListener('click',()=>$('#frame-dialog').close());$('#frame-a').addEventListener('click',()=>showFrame(DOC.shots[frameShot].id,'a'));$('#frame-b').addEventListener('click',()=>showFrame(DOC.shots[frameShot].id,'b'));$('#frame-dialog').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();showFrame(DOC.shots[frameShot].id,e.key==='ArrowLeft'?'a':'b')}});
function showPrompt(i){promptIndex=i;if($('#camera-schedule'))$('#camera-schedule').hidden=PROMPTS[i].kind!=='timed';$('#prompt-text').value=PROMPTS[i].text;$('#prompt-text').setSelectionRange(0,0);$('#prompt-text').scrollTop=0;$('#prompt-caption').textContent=PROMPTS[i].caption;$$('[data-prompt]').forEach(b=>{const active=Number(b.dataset.prompt)===i;b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1});$('#copy-prompt').textContent='复制这份提示词';$('#copy-prompt').dataset.copyState='idle'}
$('#prompt-tabs').addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();let i=e.key==='Home'?0:e.key==='End'?PROMPTS.length-1:(promptIndex+(e.key==='ArrowRight'?1:-1)+PROMPTS.length)%PROMPTS.length;showPrompt(i);$(`[data-prompt="${i}"]`).focus()}});
$('#copy-prompt').addEventListener('click',async()=>{let copied=false;try{await navigator.clipboard.writeText($('#prompt-text').value);copied=true}catch(e){$('#prompt-text').focus();$('#prompt-text').select();copied=document.execCommand('copy')}if(copied){$('#prompt-text').setSelectionRange(0,0);$('#prompt-text').scrollTop=0;$('#copy-prompt').focus({preventScroll:true})}$('#copy-prompt').dataset.copyState=copied?'success':'failed';$('#copy-prompt').textContent=copied?'已复制 ✓':'请选中文字复制';toast(copied?'提示词已复制，可直接粘贴使用':'自动复制不可用，文本已选中')});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.seek!==undefined)seek(Number(b.dataset.seek));if(b.dataset.segment)seek(DOC.shots.find(s=>s.id===b.dataset.segment).start);if(b.dataset.category){category=b.dataset.category;renderShots()}if(b.dataset.cast){castId=castId===b.dataset.cast?'':b.dataset.cast;category='all';term='';$('#search').value='';renderShots();$('#shots').scrollIntoView({behavior:'smooth'})}if(b.dataset.frame){const [id,p]=b.dataset.frame.split(':');showFrame(id,p)}if(b.dataset.source)changeSource(b.dataset.source,DOC.media.find(m=>m.src===b.dataset.source)?.label||'视频');if(b.dataset.prompt!==undefined)showPrompt(Number(b.dataset.prompt))});
let localURL=null;$('#local-video').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(localURL)URL.revokeObjectURL(localURL);localURL=URL.createObjectURL(f);changeSource(localURL,'本地文件：'+f.name)});
renderShots();showPrompt(0);sync();const hash=decodeURIComponent(location.hash.slice(1));if(DOC.shots.some(s=>s.id===hash))seek(DOC.shots.find(s=>s.id===hash).start,false,null,false);
window.reportReady=true;
